import numpy as np

def loser_winner_beta(r, m, J, t, window=36, skip=1):
    f = formation_returns(r, J, skip)
    rank = np.argsort(np.argsort(f[t], kind="stable"), kind="stable")
    dec = rank * 10 // r.shape[1]
    past, mp = r[t - window:t], m[t - window:t]
    def beta(mask):
        y = past[:, mask].mean(axis=1)
        return np.cov(mp, y, ddof=1)[0, 1] / np.var(mp, ddof=1)
    return float(beta(dec == 0) - beta(dec == 9))

