import numpy as np

def vol_scaled(x, window, target, cap=1.0):
    x = np.asarray(x, dtype=float)
    out = []
    for t in range(window, len(x)):
        scale = min(cap, target / x[t - window:t].std(ddof=1))
        out.append(x[t] * scale)
    return np.array(out)
